{
  "results": [
    {
      "server": "opensip",
      "tools": [
        {
          "tool_name": "opensip__review_change",
          "description": "Use this OpenSIP MCP result tool first for PR review or changed-code review questions when OpenSIP evidence already exists. It rebuilds the v1 ReviewBrief from persisted suite step sessions, includes graph freshness, and never re-runs fit/graph/yagni/sim. Do not grep .runtime/logs, read datastore.sqlite directly, or re-run a CLI tool to answer stored review questions.",
          "score": 7.780388832092285,
          "input_schema": {
            "$schema": "http://json-schema.org/draft-07/schema#",
            "type": "object",
            "properties": {
              "suiteRunId": {
                "type": "string",
                "minLength": 1,
                "maxLength": 128
              },
              "suite": {
                "type": "string",
                "minLength": 1,
                "maxLength": 128
              },
              "files": {
                "maxItems": 100,
                "type": "array",
                "items": {
                  "type": "string",
                  "minLength": 1,
                  "maxLength": 1024
                }
              },
              "limit": {
                "type": "integer",
                "exclusiveMinimum": 0,
                "maximum": 500
              }
            },
            "additionalProperties": false
          }
        },
        {
          "tool_name": "opensip__get_runtime_wiring",
          "description": "Project live declarative tool wiring from the admitted tool registry, manifests, provenance, and the plain host+Tool command inventory captured when the MCP server started. This is NOT a source-level call graph — use trace_path from a separately resolved handler declaration for static calls. Edges are labelled by source (manifest/provenance/registry/command-spec/host-contract) with confidence and static-bridge status. Exclusive detail modes: summary (default), groups, or nodes.",
          "score": 5.028483867645264,
          "input_schema": {
            "$schema": "http://json-schema.org/draft-07/schema#",
            "type": "object",
            "properties": {
              "tool": {
                "type": "string",
                "minLength": 1,
                "maxLength": 256
              },
              "command": {
                "type": "string",
                "minLength": 1,
                "maxLength": 256
              },
              "provenanceSource": {
                "type": "string",
                "enum": [
                  "bundled",
                  "installed",
                  "user-global",
                  "project-local"
                ]
              },
              "limit": {
                "default": 100,
                "type": "integer",
                "exclusiveMinimum": 0,
                "maximum": 500
              },
              "cursor": {
                "type": "string",
                "minLength": 1,
                "maxLength": 4096,
                "pattern": "^[A-Za-z0-9_-]+$"
              },
              "groupBy": {
                "default": "none",
                "type": "string",
                "enum": [
                  "none",
                  "tool",
                  "source",
                  "owner"
                ]
              },
              "detail": {
                "default": "summary",
                "type": "string",
                "enum": [
                  "summary",
                  "groups",
                  "nodes"
                ]
              }
            },
            "additionalProperties": false
          }
        },
        {
          "tool_name": "opensip__refresh_graph",
          "description": "Ensure the MCP server is serving a fresh graph catalog. Auto-loads a newer catalog already persisted by `opensip graph` without rebuilding. Rebuilds only when the catalog is missing/stale, or when forceRebuild is true. EXPENSIVE when it rebuilds — do NOT loop it per query. Returns action (no-op|reloaded|rebuilt), generation, and freshness.",
          "score": 1.236488699913025,
          "input_schema": {
            "$schema": "http://json-schema.org/draft-07/schema#",
            "type": "object",
            "properties": {
              "forceRebuild": {
                "type": "boolean"
              }
            },
            "additionalProperties": false
          }
        },
        {
          "tool_name": "opensip__compare_to_baseline",
          "description": "Use this OpenSIP MCP result tool to compare a stored fit/graph/yagni/sim run against that tool’s saved baseline. It replays the persisted session, reads stored baseline fingerprints, returns added/unchanged/resolved counts, and never re-runs the underlying tool.",
          "score": 1.2303049564361572,
          "input_schema": {
            "$schema": "http://json-schema.org/draft-07/schema#",
            "type": "object",
            "properties": {
              "tool": {
                "type": "string",
                "minLength": 1,
                "maxLength": 64
              },
              "ref": {
                "type": "string",
                "minLength": 1,
                "maxLength": 128
              },
              "limit": {
                "type": "integer",
                "exclusiveMinimum": 0,
                "maximum": 500
              },
              "includeResolved": {
                "type": "boolean"
              }
            },
            "required": [
              "tool"
            ],
            "additionalProperties": false
          }
        },
        {
          "tool_name": "opensip__show_run",
          "description": "Use this OpenSIP MCP result tool first to replay an existing or prior fit/graph/yagni/sim result by id, or \"latest\" (with `tool`) for last-run, score, session, errors, warnings, or findings questions. Returns the decoded finding envelope plus session provenance and recommendedNext commands — the same filters/raw shape as `opensip sessions show`. Replays persisted sessions and never re-runs fit/graph/yagni/sim. Do not grep .runtime/logs, read datastore.sqlite directly, or re-run a CLI tool to answer stored-result questions.",
          "score": 1.220588207244873,
          "input_schema": {
            "$schema": "http://json-schema.org/draft-07/schema#",
            "type": "object",
            "properties": {
              "ref": {
                "type": "string",
                "minLength": 1,
                "maxLength": 128
              },
              "tool": {
                "type": "string",
                "minLength": 1,
                "maxLength": 64
              },
              "filters": {
                "maxItems": 16,
                "type": "array",
                "items": {
                  "type": "string",
                  "minLength": 1,
                  "maxLength": 64
                }
              },
              "raw": {
                "type": "boolean"
              }
            },
            "required": [
              "ref"
            ],
            "additionalProperties": false
          }
        },
        {
          "tool_name": "opensip__list_execution_runs",
          "description": "List bounded, newest-first existing canonical parent execution Runs for audit and suite context. Each row is the same parent Run DTO used by `opensip runs list --json` and points to show_execution_run for ordered step detail. This is distinct from list_runs, which lists replayable Tool Sessions. Reads persisted evidence only and never re-runs an analysis, audit, or suite. Do not inspect .runtime/logs or datastore.sqlite directly.",
          "score": 1.2061766386032104,
          "input_schema": {
            "$schema": "http://json-schema.org/draft-07/schema#",
            "type": "object",
            "properties": {
              "limit": {
                "type": "integer",
                "exclusiveMinimum": 0,
                "maximum": 500
              }
            },
            "additionalProperties": false
          }
        },
        {
          "tool_name": "opensip__show_execution_run",
          "description": "Read one exact existing canonical parent execution Run and a bounded, ordered RunStep page. The runId is exact: this tool does not resolve \"latest\", names, Tool Session ids, or fuzzy matches. Linked Sessions are returned only as follow-up ids and `opensip sessions show` commands; payloads are not hydrated. Reads persisted evidence only and never re-runs an analysis, audit, or suite. Do not inspect .runtime/logs or datastore.sqlite directly.",
          "score": 1.185827612876892,
          "input_schema": {
            "$schema": "http://json-schema.org/draft-07/schema#",
            "type": "object",
            "properties": {
              "runId": {
                "type": "string",
                "minLength": 1,
                "maxLength": 128,
                "pattern": "^[A-Za-z0-9_-]+$"
              },
              "offset": {
                "type": "integer",
                "minimum": 0,
                "maximum": 9007199254740491
              },
              "limit": {
                "type": "integer",
                "exclusiveMinimum": 0,
                "maximum": 500
              }
            },
            "required": [
              "runId"
            ],
            "additionalProperties": false
          }
        },
        {
          "tool_name": "opensip__get_file_context",
          "description": "Return bounded inventory metadata, roles, targets, package context, coverage, and freshness for one project-relative file. Unknown, excluded, and unavailable are distinct states; no source text is returned.",
          "score": 1.1825990676879883,
          "input_schema": {
            "$schema": "http://json-schema.org/draft-07/schema#",
            "type": "object",
            "properties": {
              "file": {
                "type": "string",
                "minLength": 1,
                "maxLength": 1024
              }
            },
            "required": [
              "file"
            ],
            "additionalProperties": false
          }
        },
        {
          "tool_name": "opensip__get_agent_catalog",
          "description": "The self-describing catalog of OpenSIP commands an agent can run. Before re-running for existing or prior evidence, use list_execution_runs/show_execution_run for persisted audit or suite parent execution context, and use get_latest_findings/show_run/list_runs for replayable Tool Session results, scores, errors, warnings, or findings. These read persisted evidence and never re-run fit/graph/yagni/sim, an audit, or a suite. Do not grep .runtime/logs, read datastore.sqlite directly, or re-run a CLI tool to answer stored-result questions.",
          "score": 1.1801390647888184,
          "input_schema": {
            "$schema": "http://json-schema.org/draft-07/schema#",
            "type": "object",
            "properties": {},
            "additionalProperties": false
          }
        },
        {
          "tool_name": "opensip__impact_files",
          "description": "Compute bounded changed-to-caller impact for explicit project-relative files. Inspect freshness, four-facet coverage, trust, unmatchedFiles, and nextActions before treating an empty impact set as authoritative.",
          "score": 1.1699448823928833,
          "input_schema": {
            "$schema": "http://json-schema.org/draft-07/schema#",
            "type": "object",
            "properties": {
              "files": {
                "minItems": 1,
                "maxItems": 128,
                "type": "array",
                "items": {
                  "type": "string",
                  "minLength": 1,
                  "maxLength": 1024
                }
              },
              "depth": {
                "default": 5,
                "type": "integer",
                "minimum": 1,
                "maximum": 5
              },
              "top": {
                "type": "integer",
                "exclusiveMinimum": 0,
                "maximum": 500
              }
            },
            "required": [
              "files"
            ],
            "additionalProperties": false
          }
        }
      ]
    }
  ],
  "total_hidden_tools": 54,
  "status": "ready",
  "note": null
}

