        out[k] = v
    return out


def _scan_tokens(text: str, integer_paths: set[str]) -> None:
    """Reject float/exponent/-0 tokens. Path tracking is best-effort for claimed integer fields."""
    i = 0
    n = len(text)
    while i < n:
