        if ch in " \t\r\n{}[],:":
            i += 1
            continue
        if ch == '"':
            i += 1
            while i < n:
                if text[i] == "\\":
                    i += 2
                    continue
                if text[i] == '"':
                    i += 1
                    break
                i += 1
            continue
        if ch in "-0123456789":
            j = i
            if text[j] == "-":
                j += 1
            while j < n and text[j].isdigit():
                j += 1
            if j < n and text[j] in ".eE":
                k = j
                while k < n and text[k] not in " \t\r\n{}[],:":
                    k += 1
                tok = text[i:k]
                raise AdmissionError("NON_INTEGER_TOKEN", f"numeric token {tok!r} is not an ordinary integer")
