            )
        if a.get("deficiency") not in DEFICIENCIES:
            violations.append(
                {
                    "gate": "ADM-DOMAIN",
                    "path": f"$.coverageForAbsent[{i}].deficiency",
                    "reason": f"{a.get('deficiency')!r} not in DEFICIENCY-DOMAIN-V1",
                }
            )
    domain_hits = [v for v in violations if v["gate"] == "ADM-DOMAIN"]
    if domain_hits:
        return {"admitted": False, "firstGate": "ADM-DOMAIN", "violations": violations, "masksLater": GATE_ORDER[3:]}

    # ADM-ORDER (declared traversal)
    for i, p in enumerate(providers):
        _utf8_asc_unique(list(p.get("platformIds") or []), f"$.providers[{i}].platformIds", violations)
    for i, a in enumerate(absent):
        _utf8_asc_unique(list(a.get("relationIds") or []), f"$.coverageForAbsent[{i}].relationIds", violations)
    _utf8_asc_unique([p.get("providerId") for p in providers], "$.providers", violations)
    _utf8_asc_unique([a.get("providerId") for a in absent], "$.coverageForAbsent", violations)

    order_hits = [v for v in violations if v["gate"] == "ADM-ORDER"]
    if order_hits:
        return {"admitted": False, "firstGate": "ADM-ORDER", "violations": violations, "masksLater": []}

    committed = encode_cve1(obj)
    ident = capability_manifest_id(committed)
    return {
        "admitted": True,
        "firstGate": None,
        "violations": [],
        "masksLater": [],
        "committedBytes": committed,
        "capabilityManifestId": ident,
        "capabilityManifestBytesDigest": __import__("hashlib").sha256(committed).hexdigest(),
    }


def minimal_manifest(*, profile: str, providers: list[dict], coverage_for_absent: list[dict] | None = None) -> dict:
    return {
        "schemaVersion": 1,
        "profile": profile,
        "providers": providers,
        "coverageForAbsent": coverage_for_absent or [],
    }
"}

{"file_path":"/tmp/opensip-design-corrections/consumer-b.v10/output/recon/protocol.py","content":""""Provider protocol 3 host state machine from protocol3-transitions.v1.json.

Owner: docs/coop/design-corrections/native/protocol3-transitions.v1.json
Prose-owned (not in the table): frame payloads, identity token set, D9 mapping, stage count.
"""
from __future__ import annotations

import copy
import json
from pathlib import Path
from typing import Any

KIT = Path("/tmp/opensip-design-corrections/consumer-b.v10/subject")

IDENTITY_TOKENS = [
    "source-identity-snapshot2",
    "plan-identity-plan2",
    "fact-identity-fact2",
    "coverage-v3",
]

PROCESS_FAULT = {"deadline", "nonzero-exit", "signal-death", "stdout-byte"}


def load_table() -> dict:
    p = KIT / "docs/coop/design-corrections/native/protocol3-transitions.v1.json"
    return json.loads(p.read_text())


def identity_negotiated(hello_ack: dict) -> bool:
    caps = hello_ack.get("capabilities") or []
    return all(t in caps for t in IDENTITY_TOKENS)


class Protocol3:
    def __init__(self, table: dict | None = None, *, stage_count: int = 1):
        self.table = table or load_table()
        self.stage_count_override = stage_count
        self.reset()

    def reset(self) -> None:
        self.state = copy.deepcopy(self.table["initialState"])
        self.trace: list[str] = []
        self.source_bytes_sent_before_identity = False

    @property
    def phase(self) -> str:
        return self.state["phase"]

    def apply(self, frame: str, payload: dict | None = None) -> dict:
        payload = payload or {}
        pre = self._pre_match(frame)
        if pre:
            return pre
        row = self._match(frame)
        if row is None:
            return self._no_match()
        self._state_updates(frame, payload)
        nxt = row.get("next")
        if nxt == "ANALYZING_OR_READY_COMPLETE":
            self.state["stageIndex"] = int(self.state.get("stageIndex") or 0) + 1
            self.state["stagesCompleted"] = int(self.state.get("stagesCompleted") or 0) + 1
            if self.state["stageIndex"] == self.state.get("stageCount"):
                nxt = "READY_COMPLETE"
            else:
                nxt = "ANALYZING"
        if row.get("terminal"):
            self.state["terminalKind"] = row["terminal"]
        self.state["phase"] = nxt
        self.trace.append(row["id"])
        return {"id": row["id"], "phase": self.state["phase"], "state": copy.deepcopy(self.state)}

    def _pre_match(self, frame: str) -> dict | None:
        # FAULT is absorbing — first preMatchLaw entry.
        if self.state["phase"] == "FAULT":
            self.trace.append("FAULT-absorb")
            return {"id": "FAULT-absorb", "phase": "FAULT", "state": copy.deepcopy(self.state)}
        # post-terminal frames
        if self.state["phase"] in ("WAIT_ZERO_EXIT", "WAIT_EOF", "DONE"):
            if frame not in ("zero-exit", "eof") and frame not in PROCESS_FAULT:
                self.state["phase"] = "FAULT"
                self.trace.append("post-terminal-frame")
                return {"id": "post-terminal-frame", "phase": "FAULT", "state": copy.deepcopy(self.state)}
        # *PROCESS_FAULT from any phase → P3-33
        if frame in PROCESS_FAULT:
            self.state["phase"] = "FAULT"
            self.trace.append("P3-33")
            return {"id": "P3-33", "phase": "FAULT", "state": copy.deepcopy(self.state)}
        return None

    def _match(self, frame: str) -> dict | None:
        wild = self.table["wildcards"]["*PRE_COMPLETE"]["phases"]
        for row in self.table["rules"]:
            if row["phase"] == "*ANY":
                continue  # skipped by matching loop; applied by pre/no-match
            phase_ok = row["phase"] == self.state["phase"] or (
                row["phase"] == "*PRE_COMPLETE" and self.state["phase"] in wild
            )
            if not phase_ok:
                continue
            if row.get("frame") != frame:
                continue
            guard = row.get("guard") or {}
            ok = True
            for k, v in guard.items():
                if self.state.get(k) != v:
                    ok = False
                    break
            if ok:
                return row
        return None

    def _no_match(self) -> dict:
        self.state["phase"] = "FAULT"
        self.trace.append("P3-34")
        return {"id": "P3-34", "phase": "FAULT", "state": copy.deepcopy(self.state)}

    def _state_updates(self, frame: str, payload: dict) -> None:
        if frame == "HelloAck":
            self.state["identityNegotiated"] = identity_negotiated(payload)
        if frame == "OpenUniverse":
            self.state["dependencyMode"] = bool(payload.get("dependencyMode", False))
            self.state["preparedMode"] = bool(payload.get("preparedMode", False))
        if frame == "Analyze":
            self.state["stageCount"] = int(payload.get("stageCount", self.stage_count_override))
            self.state["stageIndex"] = 0
        source_frames = {
            "DependencySourceChunk",
            "DependencySourceManifest",
            "OpenUniverse",
            "PreparedOutputChunk",
            "PreparedOutputManifest",
            "SnapshotFileChunk",
            "SnapshotManifest",
        }
        if frame in source_frames:
            if not self.state.get("identityNegotiated"):
                self.source_bytes_sent_before_identity = True
            self.state["sourceBytesSent"] = True


def rust_hello_caps() -> list[str]:
    return [
        "source-identity-snapshot2",
        "plan-identity-plan2",
        "fact-identity-fact2",
        "coverage-v3",
        "sealed-vfs-v1",
        "multi-stage-analyze-v1",
        "rust-semantic-facts-v1",
        "resolution-completeness-v2",
        "unresolved-edge-v1",
        "dependency-source-v1",
        "prepared-output-v3",
        "native-context-v2",
    ]


def identity_versions() -> dict:
    return {"snapshot": 2, "plan": 2, "fact": 2, "coverage": 3}


def run_trace(events: list[tuple[str, dict]], *, stage_count: int = 1) -> dict:
    p = Protocol3(stage_count=stage_count)
    steps = []
    for frame, payload in events:
        steps.append(p.apply(frame, payload))
    return {
        "trace": list(p.trace),
        "phase": p.phase,
        "state": p.state,
        "sourceBytesSent": p.state.get("sourceBytesSent"),
        "identityNegotiated": p.state.get("identityNegotiated"),
        "sourceBytesSentBeforeIdentity": p.source_bytes_sent_before_identity,
        "steps": [{"id": s["id"], "phase": s["phase"]} for s in steps],
    }
"}

{"file_path":"/tmp/opensip-design-corrections/consumer-b.v10/output/recon/schema_val.py","content":""""Draft 2020-12 schema validation against kit documents."""
from __future__ import annotations

import json
from pathlib import Path
from typing import Any

from jsonschema import Draft202012Validator
from referencing import Registry, Resource
from referencing.jsonschema import DRAFT202012

KIT = Path("/tmp/opensip-design-corrections/consumer-b.v10/subject")


def _collect_schemas() -> list[tuple[str, dict, Path]]:
    out = []
    for p in sorted((KIT / "docs").rglob("*.json")):
        try:
            obj = json.loads(p.read_text())
        except Exception:
            continue
        if isinstance(obj, dict) and obj.get("$schema") and (obj.get("$id") or "$defs" in obj):
            sid = obj.get("$id") or str(p)
            out.append((sid, obj, p))
    return out


_SCHEMAS = _collect_schemas()
_BY_ID = {sid: obj for sid, obj, _ in _SCHEMAS}
_BY_SUFFIX: dict[str, dict] = {}
for sid, obj, p in _SCHEMAS:
    _BY_SUFFIX[p.name] = obj
    rel = str(p.relative_to(KIT / "docs"))
    _BY_SUFFIX[rel] = obj


def _registry() -> Registry:
    reg = Registry()
    for sid, obj, _ in _SCHEMAS:
        reg = reg.with_resource(sid, Resource.from_contents(obj, default_specification=DRAFT202012))
    return reg


REGISTRY = _registry()


def schema_by_id(sid: str) -> dict:
    if sid not in _BY_ID:
        raise KeyError(sid)
    return _BY_ID[sid]


def validate_against(instance: Any, schema: dict, *, selector: str | None = None) -> list[str]:
    target = schema
    if selector:
        if not selector.startswith("#/"):
            raise ValueError(selector)
        cur: Any = schema
        for part in selector[2:].split("/"):
            part = part.replace("~1", "/").replace("~0", "~")
            cur = cur[part]
        target = cur
        if "$id" not in target:
            # keep parent $id for $ref resolution
            wrapped = {
                "$schema": schema.get("$schema", "https://json-schema.org/draft/2020-12/schema"),
                "$id": schema.get("$id", "urn:opensip:local"),
                "$defs": schema.get("$defs", {}),
                "type": target.get("type", "object"),
            }
            wrapped.update({k: v for k, v in target.items() if k != "$defs"})
            target = wrapped
    try:
        validator = Draft202012Validator(target, registry=REGISTRY)
    except Exception:
        validator = Draft202012Validator(target)
    errs = sorted(validator.iter_errors(instance), key=lambda e: list(e.path))
    return [f"{'/'.join(str(p) for p in e.absolute_path) or '$'}: {e.message}" for e in errs]


def validate_def(instance: Any, document_rel: str, def_name: str) -> list[str]:
    p = KIT / "docs" / document_rel if not document_rel.startswith("/") else Path(document_rel)
    if not p.exists():
        p = KIT / document_rel
    schema = json.loads(p.read_text())
    return validate_against(instance, schema, selector=f"#/$defs/{def_name}")


def validate_root(instance: Any, document_rel: str) -> list[str]:
    p = KIT / "docs" / document_rel
    if not p.exists():
        p = KIT / document_rel
    schema = json.loads(p.read_text())
    return validate_against(instance, schema)
"}

{"file_path":"/tmp/opensip-design-corrections/consumer-b.v10/output/recon/evaluator.py","content":""""Independent evaluator3 reconstruction from composition + atom contracts.

Does not read claimed findings/witnesses to select subjects or values.
"""
from __future__ import annotations

from typing import Any

from .codec import (
    AdmissionError,
    canonical_digest,
    encode_c,
    h_hex,
    h_id,
    sha256,
    sort_canonical_set,
    sort_utf8,
)

UNIVERSE_MAP = {
    "typescript": "native.semantic-universe.typescript.v2",
    "rust": "native.semantic-universe.rust.v2",
    "syntax": "native.semantic-universe.syntax.v2",
}

LADDERS = {
    "calls": ["syntactic-callee-name", "resolved-callee"],
    "clones": ["normalized-body-hash"],
    "control-flow": ["syntactic"],
    "declares": ["syntactic"],
    "file": ["enumerated"],
    "imports": ["syntactic-specifier", "resolved-target"],
    "literal": ["syntactic"],
    "package": ["manifest-declared"],
    "reachability": ["from-resolved-calls"],
    "references": ["syntactic-name-match", "resolved-binding"],
    "types": ["annotated", "checked"],
    "unresolved-edge": ["observed"],
    "vcs-change": ["vcs-reported"],
    "runtime-observation": ["observed"],
    "history-change": ["observed"],
}

SEV_ORDER = {"note": 0, "warning": 1, "error": 2}

TRUE, FALSE, UNKNOWN = "true", "false", "indeterminate"


def kleene_not(v: str) -> str:
    if v == TRUE:
        return FALSE
    if v == FALSE:
        return TRUE
    return UNKNOWN


def kleene_and(vals: list[str]) -> str:
    if any(v == FALSE for v in vals):
        return FALSE
    if all(v == TRUE for v in vals):
        return TRUE
    return UNKNOWN


def kleene_or(vals: list[str]) -> str:
    if any(v == TRUE for v in vals):
        return TRUE
    if all(v == FALSE for v in vals):
        return FALSE
    return UNKNOWN


def predicate_children(node: dict, addr: str) -> list[tuple[str, dict]]:
    op = node["op"]
    if op in ("and", "or"):
        return [(f"{addr}.{i}", n) for i, n in enumerate(node["operands"])]
    if op == "not":
        return [(f"{addr}.0", node["operand"])]
    return []


def is_atom(node: dict) -> bool:
    return node["op"] in ("exists", "none", "count-at-most", "all-covered")


def rung_index(relation: str, rung: str) -> int:
    ladder = LADDERS.get(relation)
    if not ladder:
        raise AdmissionError("ATOM_RELATION_UNREGISTERED", relation)
    if rung not in ladder:
        raise AdmissionError("ATOM_RUNG_NOT_IN_LADDER", f"{relation}@{rung}")
    return ladder.index(rung)


def occupancy_id(fact: dict, payload: dict, endpoint: str, subject_kind: str) -> str | None:
    rel = fact["relation"]
    if endpoint == "source":
        if rel == "file":
            return payload.get("path")
        if rel == "package":
            return payload.get("packageName")
        if rel == "clones":
            # source-path: anchors[0].path
            an = fact.get("anchors") or []
            return an[0]["path"] if an else None
        if rel in ("declares",):
            return payload.get("declared") if subject_kind == "symbol" else payload.get("container")
        if rel == "imports":
            return payload.get("importer")
        if rel == "calls":
            return payload.get("caller")
        if rel == "literal":
            return payload.get("owner")
        if rel == "types":
            return payload.get("subject")
        if rel == "unresolved-edge":
            return payload.get("referrer")
        if rel == "vcs-change":
            return payload.get("path") if "path" in payload else None
    return None


def fact_matches_atom(atom: dict, fact: dict, payload: dict, subject: dict) -> bool:
    if fact["relation"] != atom["relation"]:
        return False
    want = rung_index(atom["relation"], atom["minResolution"])
    got = rung_index(fact["relation"], fact["resolution"])
    if got < want:
        return False
    # universe: default same-only for most; filter may constrain
    native = subject["nativeSubjectId"]
    endpoint = atom.get("endpoint") or "source"
    occ = occupancy_id(fact, payload, endpoint, subject["kind"])
    if occ is None:
        return False
    if occ != native:
        # package also matches manifestPath
        if fact["relation"] == "package" and subject["kind"] == "package":
            if payload.get("packageName") != native:
                return False
            mp = subject.get("packageManifestPath")
            if mp and payload.get("manifestPath") != mp:
                return False
        else:
            return False
    for flt in atom.get("filters") or []:
        if not apply_filter(flt, fact, payload, subject):
            return False
    return True


def apply_filter(flt: dict, fact: dict, payload: dict, subject: dict) -> bool:
    field, cmp_, value = flt["field"], flt["cmp"], flt["value"]
    actual: Any
    if field == "resolution":
        actual = fact["resolution"]
    elif field == "universe":
        actual = None  # portable domain comparison is admission-time for illegal values
        return True
    elif field == "confidenceMillionths":
        actual = fact["confidenceMillionths"]
    elif field == "subject":
        actual = occupancy_id(fact, payload, "source", subject["kind"])
    else:
        actual = payload.get(field)
    if cmp_ == "eq":
        return actual == value
    if cmp_ == "neq":
        return actual != value
    if cmp_ == "in":
        return actual in (value if isinstance(value, list) else [value])
    return False


def coverage_for_atom(atom: dict, coverages: list[dict], scopes: dict, subject: dict) -> list[dict]:
    """Exact-rung coverages whose scope contains the current source subject."""
    out = []
    for cov in coverages:
        payload = cov["payload"]
        if payload["key"]["relation"] != atom["relation"]:
            continue
        if payload["key"]["resolution"] != atom["minResolution"]:
            continue
        if payload["key"]["sourceUniverse"] != subject["universe"]:
            continue
        scope = scopes[cov["scopeId"]]
        if subject["nativeSubjectId"] not in scope["subjects"]:
            continue
        out.append(cov)
    return out


def atom_completeness(atom: dict, matching_covs: list[dict]) -> tuple[str, list[str]]:
    """Returns (completeness, causes). complete vs unknown vs missing."""
    if not matching_covs:
        return "missing", ["missing-relation-coverage"]
    # If any covering complete with null deficiency at exact rung: complete
    complete = False
    unknown = False
    causes = []
    for cov in matching_covs:
        entry = cov["payload"]["entry"]
        if entry["coverage"] == "complete" and entry.get("deficiency") is None:
            complete = True
        else:
            unknown = True
            if entry.get("deficiency"):
                causes.append(entry["deficiency"])
            else:
                causes.append("coverage-unknown")
    if complete and not unknown:
        return "complete", []
    if complete and unknown:
        # known matches still dominate for exists/none; completeness for none-true needs all
        return "partial", causes
    return "unknown", causes or ["coverage-unknown"]


def evaluate_atom(
    atom: dict,
    subject: dict,
    facts: list[dict],
    payloads: dict[str, dict],
    coverages: list[dict],
    scopes: dict,
) -> dict:
    matching = []
    for fact in facts:
        pl = payloads[fact["id"]]
        if fact_matches_atom(atom, fact, pl, subject):
            matching.append(fact)
    covs = coverage_for_atom(atom, coverages, scopes, subject)
    completeness, causes = atom_completeness(atom, covs)
    known_ids = [f["id"] for f in matching]
    op = atom["op"]
    value = UNKNOWN
    if op == "exists":
        if known_ids:
            value = TRUE
        elif completeness == "complete":
            value = FALSE
        else:
            value = UNKNOWN
    elif op == "none":
        if known_ids:
            value = FALSE
        elif completeness == "complete":
            value = TRUE
        else:
            value = UNKNOWN
    elif op == "count-at-most":
        n = atom["n"]
        if len(known_ids) > n:
            value = FALSE
        elif completeness == "complete" and len(known_ids) <= n:
            value = TRUE
        else:
            value = UNKNOWN
    elif op == "all-covered":
        if completeness == "complete" and not causes:
            # sufficiency_v2 simplified: complete coverage at requested rung
            value = TRUE
        else:
            value = UNKNOWN
    deficiencies = []
    if value == UNKNOWN:
        for c in causes:
            deficiencies.append(c)
    return {
        "value": value,
        "knownFactIds": known_ids,
        "uncertainFactIds": [],
        "coverageIds": [c["id"] for c in covs],
        "causes": causes,
        "deficiencies": deficiencies,
        "kind": "native-atom",
    }


def eval_node(
    node: dict,
    addr: str,
    subject: dict,
    facts: list[dict],
    payloads: dict[str, dict],
    coverages: list[dict],
    scopes: dict,
    acc: dict,
) -> dict:
    children = predicate_children(node, addr)
    child_results = []
    for ca, cn in children:
        child_results.append(eval_node(cn, ca, subject, facts, payloads, coverages, scopes, acc))
    if is_atom(node):
        res = evaluate_atom(node, subject, facts, payloads, coverages, scopes)
        res["addr"] = addr
        res["op"] = node["op"]
        res["childAddrs"] = []
        acc[addr] = res
        return res
    op = node["op"]
    child_vals = [c["value"] for c in child_results]
    if op == "and":
        value = kleene_and(child_vals)
    elif op == "or":
        value = kleene_or(child_vals)
    elif op == "not":
        value = kleene_not(child_vals[0])
    else:
        raise AdmissionError("PRED_OP", op)
    res = {
        "value": value,
        "knownFactIds": [],
        "uncertainFactIds": [],
        "coverageIds": [],
        "causes": [],
        "deficiencies": [],
        "kind": "boolean",
        "addr": addr,
        "op": op,
        "childAddrs": [c["addr"] for c in child_results],
    }
    acc[addr] = res
    return res


def enumerate_subjects(rule: dict, inventories: list[dict], universe_hex_by_token: dict[str, str]) -> dict:
    se = rule["subjectEnumeration"]
    token = se["universe"]
    if token not in UNIVERSE_MAP:
        raise AdmissionError("POLICY_UNIVERSE_TOKEN", token)
    domain = UNIVERSE_MAP[token]
    kind = se["subjectKind"]
    if kind == "export":
        row_kind = "symbol"
        export_filter = "exported"
    else:
        row_kind = kind
        export_filter = None
    selected = []
    unresolved = []
    incomplete = []
    inventory_refs = []
    covering = False
    for inv in inventories:
        if inv["kind"] != row_kind:
            continue
        covering = True
        inventory_refs.append(inv["digest"])
        if inv["state"] != "complete":
            incomplete.append(inv["digest"])
        for row in inv["rows"]:
            if export_filter:
                if row.get("exported") == "unknown":
                    unresolved.append(row)
                    continue
                if row.get("exported") != "exported":
                    continue
            # include/exclude globs — absent or [] means all; exclusion wins
            path = row["path"]
            include = se.get("include")
            exclude = se.get("exclude") or []
            if include:
                if not any(glob_match(g, path) for g in include):
                    continue
            if any(glob_match(g, path) for g in exclude):
                continue
            selected.append(row)
    if not covering:
        return {
            "state": "incomplete",
            "selected": [],
            "unresolved": [],
            "incomplete": [],
            "inventoryRefs": [],
            "cause": "no-covering-program",
            "universeHex": universe_hex_by_token[token],
            "kind": row_kind,
        }
    state = "complete" if not incomplete and not unresolved else "incomplete"
    return {
        "state": state,
        "selected": selected,
        "unresolved": unresolved,
        "incomplete": incomplete,
        "inventoryRefs": inventory_refs,
        "cause": None,
        "universeHex": universe_hex_by_token[token],
        "kind": row_kind,
    }


def glob_match(pattern: str, path: str) -> bool:
    """Closed glob: literal, *, ?, whole-segment **. Composition says **/*.ts matches root a.ts."""
    import re as _re

    segs_p = pattern.split("/")
    segs_s = path.split("/")

    def rec(pi: int, si: int) -> bool:
        if pi == len(segs_p):
            return si == len(segs_s)
        p = segs_p[pi]
        if p == "**":
            # match zero or more segments, including matching a file at root
            if pi == len(segs_p) - 1:
                return True
            for k in range(si, len(segs_s) + 1):
                if rec(pi + 1, k):
                    return True
            return False
        if si >= len(segs_s):
            return False
        rx = "^" + _re.escape(p).replace(r"\*", "[^/]*").replace(r"\?", "[^/]") + "$"
        if _re.match(rx, segs_s[si]):
            return rec(pi + 1, si + 1)
        return False

    return rec(0, 0)


def subject_descriptor(universe_hex: str, kind: str, row: dict) -> dict:
    rec: dict[str, Any] = {
        "schemaVersion": 3,
        "universe": universe_hex,
        "kind": kind,
        "nativeSubjectId": row["nativeSubjectId"],
    }
    if kind == "package":
        rec["packageManifestPath"] = row["path"]
    return rec


def evaluate_policy(
    *,
    policy: dict,
    program: dict,
    inventories: list[dict],
    facts: list[dict],
    fact_payloads: dict[str, dict],
    coverages: list[dict],
    scopes: dict[str, dict],
    universe_hex_by_token: dict[str, str],
    waivers: dict,
    emission_plan: dict,
    detector_closure: str,
    budget_limit: int,
) -> dict:
    """Return computed proof pieces: enumerations, witnesses, findings, verdict."""
    rule_results = []
    all_findings = []
    all_witness_records = []
    all_pred_proofs = []
    execution_deficiencies: list[dict] = []

    enabled_rules = [r for r in policy["rules"] if r["enabled"]]
    # budget preflight
    S = 0
    work = 0
    # estimate after enumeration
    enum_by_rule = {}
    for rule in policy["rules"]:
        if not rule["enabled"]:
            enum_by_rule[rule["ruleId"]] = {
                "state": "disabled",
                "selected": [],
                "unresolved": [],
                "incomplete": [],
                "inventoryRefs": [],
                "cause": None,
                "universeHex": universe_hex_by_token.get(rule["subjectEnumeration"]["universe"], ""),
                "kind": rule["subjectEnumeration"]["subjectKind"],
            }
            continue
        enum_by_rule[rule["ruleId"]] = enumerate_subjects(rule, inventories, universe_hex_by_token)

    # Charge E + sum (N + A*(F+I+K))
    E = sum(len(inv.get("rows") or []) for inv in inventories) + len(inventories)
    F = len(facts)
    K = len(coverages)
    I = 0
    work = E
    for rule in enabled_rules:
        nodes = _count_nodes(rule["emitWhen"])
        atoms = _count_atoms(rule["emitWhen"])
        s = len(enum_by_rule[rule["ruleId"]]["selected"])
        work += s * (nodes + atoms * (F + I + K))
    budget_exhausted = work > budget_limit

    for rule in policy["rules"]:
        rid = rule["ruleId"]
        enum = enum_by_rule[rid]
        if not rule["enabled"]:
            rule_results.append(
                {
                    "ruleId": rid,
                    "enumeration": _enum_out(enum, [], []),
                    "outcome": "disabled",
                    "findingIds": [],
                    "deficiencies": [],
                }
            )
            continue
        if budget_exhausted:
            # empty predicates/findings, actual enumeration, indeterminate if gating
            outcome = "indeterminate" if rule["gate"] else "pass"
            rule_results.append(
                {
                    "ruleId": rid,
                    "enumeration": _enum_out(enum, [], []),
                    "outcome": outcome,
                    "findingIds": [],
                    "deficiencies": [],
                }
            )
            continue

        finding_ids = []
        defics = []
        subject_values = []
        for row in enum["selected"]:
            subj_rec = subject_descriptor(enum["universeHex"], enum["kind"], row)
            subj_id = h_id("evaluation-subject", subj_rec)
            subj = {
                **subj_rec,
                "id": subj_id,
                "path": row["path"],
                "qualifiedName": row["qualifiedName"],
                "language": row["subjectLanguage"],
            }
            acc: dict = {}
            root = eval_node(rule["emitWhen"], "p", subj, facts, fact_payloads, coverages, scopes, acc)
            subject_values.append(root["value"])
            # retain every node as witness + predicate proof
            for addr, node_res in acc.items():
                wit, pred, proof_row = _materialize_node(
                    rule, program, subj, addr, node_res, acc
                )
                all_witness_records.append(wit)
                all_pred_proofs.append(proof_row)
            if root["value"] == TRUE:
                finding = emit_finding(rule, emission_plan, subj, acc, detector_closure)
                all_findings.append(finding)
                finding_ids.append(finding["id"])
            elif root["value"] == UNKNOWN:
                defics.append(
                    {
                        "source": "native",
                        "cause": (acc["p"].get("causes") or ["coverage-unknown"])[0]
                        if acc["p"].get("causes")
                        else "missing-relation-coverage",
                        "subjectId": subj_id,
                        "predicateId": "p",
                        "inputRefs": [],
                        "evidenceKind": None,
                        "nativeCause": None,
                        "universe": enum["universeHex"],
                    }
                )

        # rule outcome
        live_unwaived = [fid for fid in finding_ids]  # no waivers in synthetic
        gating = rule["enabled"] and rule["gate"] and SEV_ORDER[rule["severity"]] >= SEV_ORDER[policy["gateSeverityAtLeast"]]
        if gating and live_unwaived:
            outcome = "fail"
        elif gating and (enum["state"] != "complete" or any(v == UNKNOWN for v in subject_values) or enum["unresolved"] or enum["incomplete"]):
            outcome = "indeterminate"
        else:
            outcome = "pass"
        if not gating:
            outcome = "pass"
        selected_ids = [h_id("evaluation-subject", subject_descriptor(enum["universeHex"], enum["kind"], row)) for row in enum["selected"]]
        unresolved_ids = [h_id("evaluation-subject", subject_descriptor(enum["universeHex"], enum["kind"], row)) for row in enum["unresolved"]]
        rule_results.append(
            {
                "ruleId": rid,
                "enumeration": _enum_out(enum, selected_ids, unresolved_ids),
                "outcome": outcome,
                "findingIds": sorted(finding_ids),
                "deficiencies": defics,
            }
        )

    if budget_exhausted:
        execution_deficiencies.append(
            {
                "source": "execution",
                "cause": "work-budget-exhausted",
                "subjectId": None,
                "predicateId": None,
                "inputRefs": [],
                "evidenceKind": None,
                "nativeCause": None,
                "universe": None,
            }
        )

    # sealed verdict
    outcomes = [rr["outcome"] for rr in rule_results]
    if any(o == "fail" for o in outcomes):
        verdict = "fail"
    elif any(o == "indeterminate" for o in outcomes) or execution_deficiencies:
        verdict = "indeterminate"
    else:
        verdict = "pass"

    return {
        "ruleResults": sorted(rule_results, key=lambda r: r["ruleId"]),
        "findings": all_findings,
        "witnesses": all_witness_records,
        "predicateProofs": all_pred_proofs,
        "verdict": verdict,
        "evaluationState": "budget-exhausted" if budget_exhausted else "evaluated",
        "executionDeficiencies": execution_deficiencies,
        "workUnitsCharged": work,
        "budgetExhausted": budget_exhausted,
    }


def _count_nodes(node: dict) -> int:
    n = 1
    for _, ch in predicate_children(node, "p"):
        n += _count_nodes(ch)
    return n


def _count_atoms(node: dict) -> int:
    if is_atom(node):
        return 1
    return sum(_count_atoms(ch) for _, ch in predicate_children(node, "p"))


def _enum_out(enum: dict, selected_ids: list[str], unresolved_ids: list[str]) -> dict:
    return {
        "state": enum["state"] if enum["state"] != "disabled" else "disabled",
        "inventoryRefs": [{"domain": "subject-inventory", "digest": d} for d in sorted(enum["inventoryRefs"])],
        "selectedSubjectIds": sorted(selected_ids),
        "unresolvedSubjectIds": sorted(unresolved_ids),
        "incompleteInventoryRefs": [{"domain": "subject-inventory", "digest": d} for d in sorted(enum["incomplete"])],
    }


def _materialize_node(rule, program, subj, addr, node_res, acc):
    op = node_res["op"]
    node_obj = _node_at(rule["emitWhen"], addr)
    node_digest = canonical_digest(node_obj)
    prog_pred = {
        "schemaVersion": 2,
        "ruleProgramDigest": canonical_digest(program),
        "ruleId": rule["ruleId"],
        "predicateId": addr,
        "operation": op,
        "nodeDigest": node_digest,
    }
    kind = node_res["kind"]
    wit = {
        "schemaVersion": 3,
        "programPredicateDigest": canonical_digest(prog_pred),
        "matchingFactIds": sorted(node_res.get("knownFactIds") or []),
        "coverageIds": sorted(node_res.get("coverageIds") or []),
        "countLimit": None,
        "childPredicateIds": sorted(node_res.get("childAddrs") or []),
        "matchingImportRows": [],
        "uncertainFactIds": [],
        "uncertainImportRows": [],
        "deficiencies": [],
        "kind": kind,
    }
    if op == "count-at-most":
        wit["countLimit"] = node_obj.get("n")
    proof_row = {
        "ruleId": rule["ruleId"],
        "subjectId": subj["id"],
        "predicateId": addr,
        "operation": op,
        "inputRefs": [],
        "scopeIds": [],
        "value": node_res["value"],
        "witnessDigest": canonical_digest(wit),
    }
    return wit, prog_pred, proof_row


def _node_at(root: dict, addr: str) -> dict:
    if addr == "p":
        return root
    assert addr.startswith("p.")
    parts = addr.split(".")[1:]
    cur = root
    for p in parts:
        i = int(p)
        if cur["op"] == "not":
            cur = cur["operand"]
        else:
            cur = cur["operands"][i]
    return cur


def emit_finding(rule, emission_plan, subj, acc, detector_closure) -> dict:
    root = acc["p"]
    params = {
        "schemaVersion": 2,
        "messageCode": rule.get("messageCode") or rule["ruleId"],
        "parameters": {
            "ruleId": rule["ruleId"],
            "subjectPath": subj["path"],
            "qualifiedName": subj["qualifiedName"],
            "subjectKind": subj["kind"],
            "subjectLanguage": subj["language"],
            "matchingFactCount": _union_match_count(acc),
            "matchingImportCount": 0,
        },
    }
    # file/package discriminator SHA256(C([]))
    disc = sha256(encode_c([]))
    fp_desc = {
        "schemaVersion": 2,
        "ruleStableId": rule["ruleProgramRef"]["ruleStableId"],
        "detectorSemanticsMajor": rule["ruleProgramRef"]["semanticsMajor"],
        "subjectKey": {
            "language": subj["language"],
            "kind": subj["kind"],
            "logicalPath": subj["path"],
            "qualifiedName": subj["qualifiedName"],
            "discriminator": disc,
        },
        "relatedSubjectKeys": [],
    }
    fp_id = h_id("finding-fingerprint", fp_desc)
    evidence = [{"domain": "predicate-witness", "digest": canonical_digest(_dummy_root_wit(rule, acc, subj))}]
    finding = {
        "schemaVersion": 3,
        "fingerprint": fp_id,
        "ruleClosure": detector_closure,
        "subjectId": subj["id"],
        "messageCode": rule.get("messageCode") or rule["ruleId"],
        "parameterDigest": canonical_digest(params),
        "severity": rule["severity"],
        "evidenceRefs": evidence,
        "ruleId": rule["ruleId"],
        "subject": {
            "language": subj["language"],
            "kind": subj["kind"],
            "logicalPath": subj["path"],
            "qualifiedName": subj["qualifiedName"],
        },
        "correspondence": {"state": "matched", "reason": None},
    }
    finding["id"] = h_id("finding", finding)
    finding["_fingerprintDesc"] = fp_desc
    finding["_params"] = params
    return finding


def _union_match_count(acc: dict) -> int:
    s = set()
    for n in acc.values():
        s.update(n.get("knownFactIds") or [])
    return len(s)


def _dummy_root_wit(rule, acc, subj):
    # placeholder; graphs layer replaces with actual witness digest
    return {
        "schemaVersion": 3,
        "programPredicateDigest": "0" * 64,
        "matchingFactIds": sorted(acc["p"].get("knownFactIds") or []),
        "coverageIds": sorted(acc["p"].get("coverageIds") or []),
        "countLimit": None,
        "childPredicateIds": sorted(acc["p"].get("childAddrs") or []),
        "matchingImportRows": [],
        "uncertainFactIds": [],
        "uncertainImportRows": [],
        "deficiencies": [],
        "kind": acc["p"]["kind"],
    }
"}

