                "path": "tsconfig.base.json",
                "contentSha256": sha256(b"base"),
                "kind": "tsconfig",
                "extendsResolved": [],
            },
            {
                "path": "tsconfig.strict.json",
                "contentSha256": sha256(b"strict"),
                "kind": "tsconfig",
                "extendsResolved": [],
            },
            {
                "path": "jsconfig.json",
