    atom_res = {"op": "exists", "relation": "imports", "minResolution": "resolved-target", "filters": []}
    cov_complete = [
        {
            "id": "coverage2:" + "2" * 64,
            "scopeId": "scope2:" + "3" * 64,
            "payload": {
                "key": {
                    "relation": "imports",
                    "resolution": "resolved-target",
                    "sourceUniverse": "a" * 64,
                    "targetUniverse": "a" * 64,
                    "subjectScopeCommitment": "sha256:" + "4" * 64,
                },
                "entry": {
                    "coverage": "complete",
                    "deficiency": None,
                    "relation": "imports",
                    "resolution": "resolved-target",
                },
            },
