    scopes = {"scope2:" + "3" * 64: {"subjects": ["src/a.ts"]}}
    r_insuf = evaluate_atom(atom_res, subject, [syn_fact], {syn_fact["id"]: syn_pl}, cov_complete, scopes)
    atom_syn = {"op": "exists", "relation": "imports", "minResolution": "syntactic-specifier", "filters": []}
